import { createContext, useContext, useState } from 'react';
import api from '../api/client';
import toast from 'react-hot-toast';

const AuthContext = createContext(null);

export function AuthProvider({ children }) {
    const [user, setUser] = useState(() => {
        try { return JSON.parse(localStorage.getItem('user')); } catch { return null; }
    });
    const [loading, setLoading] = useState(false);

    const login = async (username, password) => {
        setLoading(true);
        try {
            const { data } = await api.post('/auth/login', { username, password });

            localStorage.setItem('token', data.token);
            localStorage.setItem('user', JSON.stringify(data.user));

            // Critical for immediate next requests during redirection
            api.defaults.headers.common['Authorization'] = `Bearer ${data.token}`;

            setUser(data.user);
            return data.user;
        } catch (err) {
            toast.error(err.response?.data?.message || 'Login failed');
            throw err;
        } finally {
            setLoading(false);
        }
    };

    const logout = () => {
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        setUser(null);
        toast.success('Logged out successfully');
    };

    return (
        <AuthContext.Provider value={{ user, login, logout, loading }}>
            {children}
        </AuthContext.Provider>
    );
}

export const useAuth = () => useContext(AuthContext);

import { createContext, useContext, useState, useEffect, useCallback } from 'react';
import toast from 'react-hot-toast';
import { Connection, clusterApiUrl } from '@solana/web3.js';

const Web3Context = createContext(null);

const SEPOLIA_NETWORK_ID = '0xaa36a7';
const SEPOLIA_NETWORK_NAME = 'Sepolia Testnet';
const SOLANA_RPC = clusterApiUrl('devnet');

export function Web3Provider({ children }) {
    const [account, setAccount] = useState(null);
    const [chainId, setChainId] = useState(null);
    const [isConnecting, setIsConnecting] = useState(false);
    const [networkType, setNetworkType] = useState('ethereum'); // 'ethereum' or 'solana'
    const [solanaAddress, setSolanaAddress] = useState(null);

    // ????????? Ethereum Event Listeners ?????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????
    useEffect(() => {
        if (!window.ethereum) return;

        // Restore already-connected account on load
        window.ethereum.request({ method: 'eth_accounts' })
            .then(accounts => { if (accounts.length > 0) setAccount(accounts[0]); })
            .catch(console.error);

        window.ethereum.request({ method: 'eth_chainId' })
            .then(id => setChainId(id))
            .catch(console.error);

        const handleAccountsChanged = (accounts) => {
            if (accounts.length === 0) {
                setAccount(null);
                toast('Ethereum wallet disconnected', { icon: '????' });
            } else {
                setAccount(accounts[0]);
                toast.success('Ethereum account switched');
            }
        };

        const handleChainChanged = (hexChainId) => {
            setChainId(hexChainId);
            if (hexChainId !== SEPOLIA_NETWORK_ID) {
                toast.error('?????? Wrong Ethereum network! Please switch to Sepolia.');
            } else {
                toast.success('Switched to Sepolia Testnet ???');
            }
        };

        window.ethereum.on('accountsChanged', handleAccountsChanged);
        window.ethereum.on('chainChanged', handleChainChanged);

        // Cleanup to avoid memory leaks & duplicate listeners
        return () => {
            window.ethereum.removeListener('accountsChanged', handleAccountsChanged);
            window.ethereum.removeListener('chainChanged', handleChainChanged);
        };
    }, []);

    // ????????? Solana (Phantom) Event Listeners ????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????
    useEffect(() => {
        const solana = window.solana;
        if (!solana || !solana.isPhantom) return;

        // Restore existing Phantom session
        if (solana.isConnected && solana.publicKey) {
            setSolanaAddress(solana.publicKey.toString());
        }

        const handleAccountChanged = (publicKey) => {
            if (publicKey) {
                setSolanaAddress(publicKey.toString());
                toast.success('Phantom account switched');
            } else {
                setSolanaAddress(null);
                toast('Phantom wallet disconnected', { icon: '????' });
            }
        };

        solana.on('accountChanged', handleAccountChanged);

        return () => {
            solana.off('accountChanged', handleAccountChanged);
        };
    }, []);

    const connectSolana = async () => {
        setIsConnecting(true);
        try {
            const { solana } = window;
            if (!solana || !solana.isPhantom) {
                toast.error('Phantom wallet not found! Please install it.');
                window.open('https://phantom.app/', '_blank');
                return;
            }
            const response = await solana.connect();
            setSolanaAddress(response.publicKey.toString());
            setNetworkType('solana');
            toast.success('Solana wallet connected!');
        } catch (err) {
            console.error('Solana connection error:', err);
            toast.error('Failed to connect Solana wallet');
        } finally {
            setIsConnecting(false);
        }
    };

    const connectEthereum = async () => {
        if (!window.ethereum) {
            toast.error('MetaMask not found!');
            return;
        }
        setIsConnecting(true);
        try {
            const accounts = await window.ethereum.request({ method: 'eth_requestAccounts' });
            setAccount(accounts[0]);
            const currentChainId = await window.ethereum.request({ method: 'eth_chainId' });
            setChainId(currentChainId);
            setNetworkType('ethereum');
            if (currentChainId !== SEPOLIA_NETWORK_ID) {
                toast.error('?????? Not on Sepolia! Please switch networks.');
            } else {
                toast.success('Ethereum wallet connected!');
            }
        } catch (err) {
            console.error('Ethereum connection error:', err);
            toast.error('Failed to connect Ethereum wallet');
        } finally {
            setIsConnecting(false);
        }
    };

    const switchToSepolia = useCallback(async () => {
        try {
            await window.ethereum.request({
                method: 'wallet_switchEthereumChain',
                params: [{ chainId: SEPOLIA_NETWORK_ID }],
            });
        } catch (err) {
            toast.error('Failed to switch to Sepolia: ' + err.message);
        }
    }, []);

    const value = {
        account: networkType === 'ethereum' ? account : solanaAddress,
        chainId,
        networkType,
        setNetworkType,
        isConnecting,
        connect: networkType === 'ethereum' ? connectEthereum : connectSolana,
        isConnected: networkType === 'ethereum' ? !!account : !!solanaAddress,
        isCorrectNetwork: chainId === SEPOLIA_NETWORK_ID,
        solanaAddress,
        solanaRpc: SOLANA_RPC,
        switchToSepolia,
    };

    return (
        <Web3Context.Provider value={value}>
            {children}
        </Web3Context.Provider>
    );
}

export const useWeb3 = () => useContext(Web3Context);

import { useEffect, useState } from 'react';
import api from '../api/client';
import Layout from '../components/Layout';
import toast from 'react-hot-toast';

export default function Products() {
    const [products, setProducts] = useState([]);
    const [categories, setCategories] = useState([]);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState('');
    const [modal, setModal] = useState(null); // null | 'add' | 'edit'
    const [deleting, setDeleting] = useState(null);
    const [form, setForm] = useState({ name: '', quantity: '0', buy_price: '0', sale_price: '0', categorie_id: '', media_id: '' });
    const [editId, setEditId] = useState(null);
    const [saving, setSaving] = useState(false);
    const [confirmDelete, setConfirmDelete] = useState(null); // id to delete
    const [errors, setErrors] = useState({});

    const load = async () => {
        setLoading(true);
        const [p, c] = await Promise.all([api.get('/products'), api.get('/categories')]);
        setProducts(p.data.data);
        setCategories(c.data.data);
        setLoading(false);
    };
    useEffect(() => { load(); }, []);

    const openAdd = () => {
        setForm({ name: '', quantity: '0', buy_price: '0', sale_price: '0', categorie_id: categories[0]?.id || '', media_id: '' });
        setEditId(null); setErrors({}); setModal('add');
    };
    const openEdit = (p) => {
        setForm({ name: p.name, quantity: p.quantity, buy_price: p.buy_price, sale_price: p.sale_price, categorie_id: p.categorie_id || '', media_id: p.media_id || '' });
        setEditId(p.id); setErrors({}); setModal('edit');
    };

    const handleSubmit = async (e) => {
        e.preventDefault(); setSaving(true); setErrors({});
        try {
            if (modal === 'add') {
                await api.post('/products', form);
                toast.success('Product added!');
            } else {
                await api.put(`/products/${editId}`, form);
                toast.success('Product updated!');
            }
            setModal(null); load();
        } catch (err) {
            if (err.response?.data?.errors) {
                const newErrors = {};
                err.response.data.errors.forEach(e => {
                    newErrors[e.field] = e.message;
                });
                setErrors(newErrors);
            } else {
                toast.error(err.response?.data?.message || 'Error saving product');
            }
        } finally { setSaving(false); }
    };

    const handleDelete = async (id) => {
        setConfirmDelete(id);
    };

    const confirmAndDelete = async () => {
        const id = confirmDelete;
        setConfirmDelete(null);
        try {
            await api.delete(`/products/${id}`);
            toast.success('Product deleted');
            load();
        } catch (err) { 
            console.error('Delete product FAILED:', err);
            const msg = err.response?.data?.message || 'Delete failed';
            toast.error(msg, { duration: 6000 }); 
        }
    };

    const filtered = products.filter(p => p.name.toLowerCase().includes(search.toLowerCase()));

    return (
        <Layout>
            <div className="page-header">
                <div>
                    <h1 className="page-title">Products</h1>
                    <p className="page-sub">{products.length} total EV parts & products</p>
                </div>
                <button className="btn btn-primary" onClick={openAdd}>+ Add Product</button>
            </div>

            <div className="card" style={{ marginBottom: 16 }}>
                <div className="search-bar">
                    <span>????</span>
                    <input placeholder="Search products..." value={search} onChange={e => setSearch(e.target.value)} />
                </div>
            </div>

            {loading ? <div className="spinner" /> : (
                <div className="table-wrap" style={{ borderRadius: 'var(--radius)' }}>
                    <table>
                        <thead>
                            <tr><th>#</th><th>Name</th><th>Category</th><th>Qty</th><th>Buy Price</th><th>Sale Price</th><th>Date</th><th>Actions</th></tr>
                        </thead>
                        <tbody>
                            {filtered.length === 0 ? (
                                <tr><td colSpan={8} style={{ textAlign: 'center', padding: 40, color: 'var(--text-muted)' }}>No products found</td></tr>
                            ) : filtered.map((p, i) => (
                                <tr key={p.id}>
                                    <td style={{ color: 'var(--text-muted)' }}>{i + 1}</td>
                                    <td style={{ fontWeight: 500 }}>{p.name}</td>
                                    <td><span className="badge badge-primary">{p.category}</span></td>
                                    <td>
                                        <span className={`badge ${parseInt(p.quantity) > 0 ? 'badge-success' : 'badge-danger'}`}>
                                            {p.quantity}
                                        </span>
                                    </td>
                                    <td>???{parseFloat(p.buy_price).toLocaleString('en-IN')}</td>
                                    <td>???{parseFloat(p.sale_price).toLocaleString('en-IN')}</td>
                                    <td style={{ color: 'var(--text-secondary)', fontSize: 12 }}>{p.date?.split('T')[0]}</td>
                                    <td>
                                        <div style={{ display: 'flex', gap: 6 }}>
                                            <button className="btn btn-ghost btn-sm" onClick={() => openEdit(p)}>?????? Edit</button>
                                            <button className="btn btn-danger btn-sm" onClick={() => handleDelete(p.id)}>???????</button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}

            {confirmDelete && (
                <div className="modal-backdrop" onClick={() => setConfirmDelete(null)}>
                    <div className="modal modal-sm" onClick={e => e.stopPropagation()}>
                        <div className="modal-header">
                            <h3 className="modal-title">Confirm Delete</h3>
                            <button className="modal-close" onClick={() => setConfirmDelete(null)}>???</button>
                        </div>
                        <div className="modal-body" style={{ padding: '20px 0' }}>
                            <p>Are you sure you want to delete this product? This action cannot be undone.</p>
                        </div>
                        <div className="modal-footer">
                            <button className="btn btn-ghost" onClick={() => setConfirmDelete(null)}>Cancel</button>
                            <button className="btn btn-danger" onClick={confirmAndDelete}>??????? Delete Permanently</button>
                        </div>
                    </div>
                </div>
            )}
            {modal && (
                <div className="modal-backdrop" onClick={() => setModal(null)}>
                    <div className="modal" onClick={e => e.stopPropagation()}>
                        <div className="modal-header">
                            <h3 className="modal-title">{modal === 'add' ? 'Add Product' : 'Edit Product'}</h3>
                            <button className="modal-close" onClick={() => setModal(null)}>???</button>
                        </div>
                        <form onSubmit={handleSubmit}>
                            <div className="form-group">
                                <label className="form-label">Product Name *</label>
                                <input className={`form-control ${errors.name ? 'is-invalid' : ''}`} value={form.name} onChange={e => setForm(f => ({ ...f, name: e.target.value }))} required />
                                {errors.name && <div className="invalid-feedback">{errors.name}</div>}
                            </div>
                            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
                                <div className="form-group">
                                    <label className="form-label">Quantity</label>
                                    <input type="number" className={`form-control ${errors.quantity ? 'is-invalid' : ''}`} value={form.quantity} onChange={e => setForm(f => ({ ...f, quantity: e.target.value }))} />
                                    {errors.quantity && <div className="invalid-feedback">{errors.quantity}</div>}
                                </div>
                                <div className="form-group">
                                    <label className="form-label">Category *</label>
                                    <select className={`form-control ${errors.categorie_id ? 'is-invalid' : ''}`} value={form.categorie_id} onChange={e => setForm(f => ({ ...f, categorie_id: e.target.value }))} required>
                                        <option value="">Select???</option>
                                        {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                                    </select>
                                    {errors.categorie_id && <div className="invalid-feedback">{errors.categorie_id}</div>}
                                </div>
                                <div className="form-group">
                                    <label className="form-label">Buy Price (???) *</label>
                                    <input type="number" step="0.01" className={`form-control ${errors.buy_price ? 'is-invalid' : ''}`} value={form.buy_price} onChange={e => setForm(f => ({ ...f, buy_price: e.target.value }))} required />
                                    {errors.buy_price && <div className="invalid-feedback">{errors.buy_price}</div>}
                                </div>
                                <div className="form-group">
                                    <label className="form-label">Sale Price (???) *</label>
                                    <input type="number" step="0.01" className={`form-control ${errors.sale_price ? 'is-invalid' : ''}`} value={form.sale_price} onChange={e => setForm(f => ({ ...f, sale_price: e.target.value }))} required />
                                    {errors.sale_price && <div className="invalid-feedback">{errors.sale_price}</div>}
                                </div>
                            </div>
                            <div className="modal-footer">
                                <button type="button" className="btn btn-ghost" onClick={() => setModal(null)}>Cancel</button>
                                <button type="submit" className="btn btn-primary" disabled={saving}>{saving ? 'Saving???' : modal === 'add' ? '+ Add Product' : '???? Update'}</button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </Layout>
    );
}

import { useEffect, useState } from 'react';
import api from '../api/client';
import Layout from '../components/Layout';
import toast from 'react-hot-toast';
import {
    BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
    LineChart, Line, AreaChart, Area
} from 'recharts';

export default function Reports() {
    const [dailyData, setDailyData] = useState([]);
    const [monthlyData, setMonthlyData] = useState([]);
    const [loading, setLoading] = useState(true);
    const [range, setRange] = useState({ start: '', end: '' });
    const [rangeResults, setRangeResults] = useState(null);
    const [rangeLoading, setRangeLoading] = useState(false);

    const loadCharts = async () => {
        setLoading(true);
        try {
            const year = new Date().getFullYear();
            const month = String(new Date().getMonth() + 1).padStart(2, '0');
            const [d, m] = await Promise.all([
                api.get(`/reports/daily?year=${year}&month=${month}`),
                api.get(`/reports/monthly?year=${year}`)
            ]);

            // Transform data for recharts
            setDailyData(d.data.data.map(item => ({
                day: item.date.split('-')[2],
                total: parseFloat(item.total_selling_price)
            })));

            setMonthlyData(m.data.data.map(item => ({
                month: item.date.split('-')[1],
                total: parseFloat(item.total_selling_price)
            })));
        } catch (err) {
            toast.error('Failed to load reports');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => { loadCharts(); }, []);

    const handleRangeSearch = async (e) => {
        e.preventDefault();
        if (!range.start || !range.end) return;
        setRangeLoading(true);
        try {
            const r = await api.get(`/reports/range?start=${range.start}&end=${range.end}`);
            setRangeResults(r.data);
        } catch (err) {
            toast.error('Search failed');
        } finally {
            setRangeLoading(false);
        }
    };

    return (
        <Layout>
            <div className="page-header">
                <div>
                    <h1 className="page-title">Sales Reports</h1>
                    <p className="page-sub">Visualize and export supply chain performance</p>
                </div>
            </div>

            <div className="grid-2">
                <div className="card">
                    <h3 className="mb-4">Daily Sales (Current Month)</h3>
                    <div style={{ height: 300, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                        {loading ? (
                            <div className="spinner" />
                        ) : dailyData.length === 0 ? (
                            <div style={{ color: 'var(--text-muted)' }}>No sales data for this month</div>
                        ) : (
                            <ResponsiveContainer width="100%" height="100%">
                                <AreaChart data={dailyData}>
                                    <defs>
                                        <linearGradient id="colorTotal" x1="0" y1="0" x2="0" y2="1">
                                            <stop offset="5%" stopColor="var(--accent)" stopOpacity={0.3} />
                                            <stop offset="95%" stopColor="var(--accent)" stopOpacity={0} />
                                        </linearGradient>
                                    </defs>
                                    <CartesianGrid strokeDasharray="3 3" stroke="var(--border)" vertical={false} />
                                    <XAxis dataKey="day" stroke="var(--text-muted)" fontSize={12} />
                                    <YAxis stroke="var(--text-muted)" fontSize={12} tickFormatter={v => `???${v}`} />
                                    <Tooltip
                                        contentStyle={{ background: 'var(--bg-secondary)', border: '1px solid var(--border)', borderRadius: '8px' }}
                                        itemStyle={{ color: 'var(--accent-light)' }}
                                    />
                                    <Area type="monotone" dataKey="total" stroke="var(--accent)" fillOpacity={1} fill="url(#colorTotal)" />
                                </AreaChart>
                            </ResponsiveContainer>
                        )}
                    </div>
                </div>

                <div className="card">
                    <h3 className="mb-4">Monthly Sales Overview</h3>
                    <div style={{ height: 300, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                        {loading ? (
                            <div className="spinner" />
                        ) : monthlyData.length === 0 ? (
                            <div style={{ color: 'var(--text-muted)' }}>No sales recorded yet</div>
                        ) : (
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={monthlyData}>
                                    <CartesianGrid strokeDasharray="3 3" stroke="var(--border)" vertical={false} />
                                    <XAxis dataKey="month" stroke="var(--text-muted)" fontSize={12} />
                                    <YAxis stroke="var(--text-muted)" fontSize={12} tickFormatter={v => `???${v}`} />
                                    <Tooltip
                                        contentStyle={{ background: 'var(--bg-secondary)', border: '1px solid var(--border)', borderRadius: '8px' }}
                                        cursor={{ fill: 'rgba(255,255,255,0.05)' }}
                                    />
                                    <Bar dataKey="total" fill="var(--accent)" radius={[4, 4, 0, 0]} />
                                </BarChart>
                            </ResponsiveContainer>
                        )}
                    </div>
                </div>
            </div>

            <div className="card mt-4">
                <h3 className="mb-4">Custom Date Range Analysis</h3>
                <form onSubmit={handleRangeSearch} style={{ display: 'flex', gap: 16, alignItems: 'center', marginBottom: 24 }}>
                    <div className="form-group mb-0" style={{ flex: 1 }}>
                        <label className="form-label">Start Date</label>
                        <input type="date" className="form-control" value={range.start} onChange={e => setRange(r => ({ ...r, start: e.target.value }))} required />
                    </div>
                    <div className="form-group mb-0" style={{ flex: 1 }}>
                        <label className="form-label">End Date</label>
                        <input type="date" className="form-control" value={range.end} onChange={e => setRange(r => ({ ...r, end: e.target.value }))} required />
                    </div>
                    <button type="submit" className="btn btn-primary" style={{ marginTop: 24 }} disabled={rangeLoading}>
                        {rangeLoading ? '???? Searching...' : '???? Filter Reports'}
                    </button>
                </form>

                {rangeResults && (
                    <div>
                        <div className="stat-grid">
                            <div className="stat-card">
                                <div className="stat-icon" style={{ background: 'rgba(99,102,241,0.1)', color: 'var(--accent)' }}>????</div>
                                <div>
                                    <div className="stat-label">Revenue</div>
                                    <div className="stat-value">???{rangeResults.summary.total_revenue.toLocaleString()}</div>
                                </div>
                            </div>
                            <div className="stat-card">
                                <div className="stat-icon" style={{ background: 'rgba(239,68,68,0.1)', color: 'var(--danger)' }}>????</div>
                                <div>
                                    <div className="stat-label">Cost</div>
                                    <div className="stat-value">???{rangeResults.summary.total_cost.toLocaleString()}</div>
                                </div>
                            </div>
                            <div className="stat-card">
                                <div className="stat-icon" style={{ background: 'rgba(16,185,129,0.1)', color: 'var(--success)' }}>????</div>
                                <div>
                                    <div className="stat-label">Profit</div>
                                    <div className="stat-value">???{rangeResults.summary.profit.toLocaleString()}</div>
                                </div>
                            </div>
                        </div>

                        <div className="table-wrap">
                            <table>
                                <thead>
                                    <tr><th>Date</th><th>Product</th><th>Sales Qty</th><th>Revenue</th><th>Cost</th></tr>
                                </thead>
                                <tbody>
                                    {rangeResults.data.map((r, i) => (
                                        <tr key={i}>
                                            <td>{r.date}</td>
                                            <td>{r.name}</td>
                                            <td>{r.total_sales}</td>
                                            <td>???{parseFloat(r.total_selling_price).toLocaleString()}</td>
                                            <td>???{parseFloat(r.total_buying_price).toLocaleString()}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                )}
            </div>
        </Layout>
    );
}
